import pandas as pd

df = pd.DataFrame({
    "ventas": [1000, 5000, 800],
    "antiguedad_anos": [1, 5, 2]
})

def calcular_bono(fila):
    if fila["ventas"] > 2000 and fila["antiguedad_anos"] >= 3:
        return fila["ventas"] * 0.10
    return 50.0

df["bono"] = df.apply(calcular_bono, axis=1)
print(df["bono"].tolist())
